export function validateDataName(name){
 const errors=[];
 if(/[<>:"/\\|?*\u0000-\u001f]/.test(name))errors.push('Der Name enthält ein für Windows problematisches Zeichen.');
 if(/[. ]$/.test(name))errors.push('Ein Name endet nicht mit Punkt oder Leerzeichen.');
 if(/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(name))errors.push('Dieser Gerätename ist unter Windows reserviert.');
 if(!/^[a-z0-9_.-]+$/.test(name))errors.push('Für Buchdateien verwenden wir nur ASCII-Kleinbuchstaben, Ziffern, Unterstrich, Bindestrich und Punkt.');
 const match=/^rk_([0-9]{4}|undatiert)_(b[0-9]{4})\.xml$/.exec(name);
 if(!match)errors.push('Unser Muster lautet rk_<jahr>_<buch-id>.xml, zum Beispiel rk_1786_b0001.xml.');
 if(match&&match[1]==='0000')errors.push('Für eine unbekannte Datierung verwenden wir undatiert statt 0000.');
 return {ok:errors.length===0,errors,year:match?.[1]??null,book:match?.[2]??null};
}
export const SAMPLE_NAMES=['rk_1786_b0001.xml','rk_1786_b0002.xml','rk_1820_b0003.xml','rk_undatiert_b0004.xml'];
export function filterYear(names,year){return names.filter(n=>{const r=validateDataName(n);return r.ok&&(year==='all'||r.year===year);});}
export function checkNameSet(names){const folded=new Set(),ids=new Set(),errors=[];for(const name of names){const r=validateDataName(name);errors.push(...r.errors.map(e=>name+': '+e));if(folded.has(name.toLowerCase()))errors.push('Namenskollision ohne Beachtung der Groß-/Kleinschreibung: '+name);folded.add(name.toLowerCase());if(r.book&&ids.has(r.book))errors.push('Buchkennung mehrfach im maßgeblichen Bestand: '+r.book);if(r.book)ids.add(r.book);}return errors;}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function namingHTML(print=false){return `<section class="naming-guide" id="dateinamen"><p class="eyebrow">UNSERE EMPFEHLUNG FÜR BUCHDATEIEN</p><h3>Ein Name, der Menschen und Skripten hilft</h3><p><code class="filename-pattern">rk_1786_b0001.xml</code></p><dl class="name-parts"><dt>rk</dt><dd>Korpuskürzel</dd><dt>1786</dt><dd>Dokumentiertes Erscheinungsjahr; ohne bekannte Jahresangabe: <code>undatiert</code></dd><dt>b0001</dt><dd>Stabile Buchkennung, auch wenn Titel oder Datierung korrigiert werden</dd></dl><ol><li><strong>Einheitlich und aussagekräftig:</strong> dieselbe Reihenfolge, feste Stellenzahl und die Endung <code>.xml</code>. Titel und ausführliche Quellenbeschreibung stehen in den Metadaten.</li><li><strong>Plattformverträglich:</strong> kurze ASCII-Namen, Kleinbuchstaben und relative Pfade. Keine Leerzeichen, Umlaute, Doppelpunkte oder reservierten Gerätenamen; keine Namen, die sich nur in Groß-/Kleinschreibung unterscheiden. Die etablierten Metadateien <code>README.md</code>, <code>LICENSE</code>, <code>CITATION.cff</code> und <code>CHANGELOG.md</code> behalten ihre Standardschreibweise.</li><li><strong>Für Automatisierungen:</strong> das feste Muster ermöglicht Filter nach Jahr oder Buchkennung. Die Aufnahmeprüfung gleicht diese Angaben mit den maßgeblichen Metadaten ab.</li><li><strong>Änderungen geregelt:</strong> Namen nicht beiläufig wechseln. Bei korrigierter Datierung gezielt in Git umbenennen, die stabile Buchkennung erhalten und die Änderung im Changelog erklären.</li></ol>${print?`<p><strong>Filterbeispiel:</strong> <code>rk_1786_*.xml</code> wählt die entsprechend benannten Buchdateien des Jahres 1786. Unbekannte Datierungen heißen etwa <code>rk_undatiert_b0004.xml</code>.</p>`:`<div class="name-tools"><section><h4>Einen Buchdateinamen prüfen</h4><label for="filename-input">Nur der Dateiname, ohne Verzeichnispfad</label><input id="filename-input" value="rk_1786_b0001.xml" spellcheck="false" autocomplete="off"><div id="filename-result" role="status"></div><p class="small">Prüft die Namenskonvention; XML-Inhalt und tatsächliche Datierung werden dabei nicht geprüft.</p></section><section><h4>Per Dateiname filtern</h4><label for="filename-year">Jahresauswahl im kleinen Beispielbestand</label><select id="filename-year"><option value="1786">1786</option><option value="1820">1820</option><option value="undatiert">Undatiert</option><option value="all">Alle</option></select><ul id="filename-matches"></ul><pre><code id="filename-filter-code"></code></pre><p>Für die Untersuchung werden Release und Auswahlregel gemeinsam festgehalten.</p></section></div>`}<p><a href="dateinamen.md" download>Namensregeln als Markdown ↓</a> · <a href="assets/dateinamen-pruefen.py" download>Lokalen Namensprüfer herunterladen ↓</a></p></section>`;}
export function initNaming(root=document){
 const input=root.querySelector('#filename-input');if(!input)return;
 const update=()=>{const r=validateDataName(input.value);const box=root.querySelector('#filename-result');box.className=r.ok?'name-result valid':'name-result invalid';box.innerHTML=r.ok?`<strong>Entspricht unserem Muster.</strong> Jahr: ${escape(r.year)} · Buchkennung: ${escape(r.book)}.`:`<strong>Bitte anpassen:</strong><ul>${r.errors.map(e=>`<li>${escape(e)}</li>`).join('')}</ul>`;};
 const select=root.querySelector('#filename-year');const filter=()=>{root.querySelector('#filename-matches').innerHTML=filterYear(SAMPLE_NAMES,select.value).map(n=>`<li><code>${n}</code></li>`).join('');root.querySelector('#filename-filter-code').textContent=`from pathlib import Path\nfiles = sorted(Path("data/tei").glob("${select.value==='all'?'rk_*_b????.xml':'rk_'+select.value+'_*.xml'}"))`;};
 input.addEventListener('input',update);select.addEventListener('change',filter);update();filter();
}
